let CostsByMonth = (
CostsPlus
| where startofmonth(ChargePeriodStart) >= startofmonth(now(), -numberOfMonths)
| extend ChargePeriodStart = startofmonth(ChargePeriodStart)
| extend BillingPeriodStart = startofmonth(BillingPeriodStart)
);
let monthname = dynamic(['', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']);
let data = (
    CostsByMonth
    | summarize 
        BilledCost     = todouble(round(sum(BilledCost), 2)),
        EffectiveCost  = todouble(round(sum(EffectiveCost), 2)),
        ContractedCost = todouble(round(sum(ContractedCost), 2)),
        ListCost       = todouble(round(sum(ListCost), 2))
        by
        ChargePeriodStart = startofmonth(ChargePeriodStart)
    | order by ChargePeriodStart asc
    | extend CommitmentDiscountSavings = todouble(round(ContractedCost - EffectiveCost, 2))
    | extend NegotiatedDiscountSavings = todouble(round(ListCost - ContractedCost, 2))
    | extend ChargePeriod = strcat(format_datetime(ChargePeriodStart, 'yyyy-MM - '), monthname[monthofyear(ChargePeriodStart)])
);
data | extend Data = 'Billed cost' | evaluate pivot(ChargePeriod, sum(BilledCost), Data)
| union (data | extend Data = 'Effective cost'     | evaluate pivot(ChargePeriod, sum(EffectiveCost), Data))
| union (data | extend Data = 'Negotiated savings' | evaluate pivot(ChargePeriod, sum(NegotiatedDiscountSavings), Data))
| union (data | extend Data = 'Commitment savings' | evaluate pivot(ChargePeriod, sum(CommitmentDiscountSavings), Data))
